// ============================================================
// Program  : HELLO
// Purpose  : Hello World - Simple RPGLE demonstration
// Author   : IBM i Project
// Date     : 2025
// ============================================================

Ctl-Opt DftActGrp(*No) ActGrp(*Caller) Option(*SrcStmt);

// ----- Variables ----------------------------------------
Dcl-S wMessage   Char(50);
Dcl-S wName      Char(20)  Inz('IBM i Developer');

// ----- Main Logic ---------------------------------------
wMessage = 'Hello, ' + %TrimR(wName) + '! Welcome to IBM i RPGLE.';

// Display the message to the job log
Dsply wMessage;

*InLR = *On;
Return;

      **FREE
// ============================================================
// Program  : CALCTAX
// Purpose  : Business Logic - Calculate tax on a given amount
// Author   : IBM i Project
// Date     : 2025
//
// Parameters:
//   pAmount    (Input)  : Amount before tax
//   pTaxRate   (Input)  : Tax rate as a percentage (e.g., 8.5)
//   pTaxAmt    (Output) : Calculated tax amount
//   pTotal     (Output) : Total amount including tax
// ============================================================

Ctl-Opt DftActGrp(*No) ActGrp(*Caller) Option(*SrcStmt);

// ----- Procedure Interface (Parameters) -----------------
Dcl-PI CALCTAX;
  pAmount   Packed(11:2) Const;
  pTaxRate  Packed(5:2)  Const;
  pTaxAmt   Packed(11:2);
  pTotal    Packed(11:2);
End-PI;

// ----- Main Logic ---------------------------------------
pTaxAmt = pAmount * (pTaxRate / 100);
pTotal  = pAmount + pTaxAmt;

*InLR = *On;
Return;

/* ============================================================ */
/* Program  : RUNCL                                            */
/* Purpose  : CL Driver - Calls HELLO and CALCTAX programs     */
/* Author   : IBM i Project                                    */
/* Date     : 2025                                             */
/* ============================================================ */
PGM

    DCL VAR(&AMOUNT)   TYPE(*DEC) LEN(11 2) VALUE(250.00)
    DCL VAR(&TAXRATE)  TYPE(*DEC) LEN(5 2)  VALUE(8.50)
    DCL VAR(&TAXAMT)   TYPE(*DEC) LEN(11 2)
    DCL VAR(&TOTAL)    TYPE(*DEC) LEN(11 2)
    DCL VAR(&MSGTEXT)  TYPE(*CHAR) LEN(100)

    /* --- Step 1: Run the Hello World program -------------- */
    CALL PGM(HELLO)

    /* --- Step 2: Call the Tax Calculation program --------- */
    CALL PGM(CALCTAX) PARM(&AMOUNT &TAXRATE &TAXAMT &TOTAL)

    /* --- Step 3: Display the results --------------------- */
    CHGVAR VAR(&MSGTEXT) VALUE('Tax calc complete. +
                               Check job log for results.')
    SNDPGMMSG MSG(&MSGTEXT) TOPGMQ(*EXT) MSGTYPE(*INFO)

ENDPGM

