// ============================================================
// Program  : CUSIO
// Purpose  : Customer File I/O - Add, Read, and List customers
// Author   : IBM i Project
// Date     : 2025
// ============================================================

Ctl-Opt DftActGrp(*No) ActGrp(*Caller) Option(*SrcStmt);

// ----- File Declarations --------------------------------
Dcl-F CUSFILE Usage(*Update:*Output:*Delete) Keyed;

// ----- Data Structure for Customer Record ---------------
Dcl-DS dsCus ExtName('CUSFILE') End-DS;

// ----- Variables ----------------------------------------
Dcl-S wAction   Char(1);
Dcl-S wFound    Ind;

// ----- Main Logic ---------------------------------------

// --- ADD a new customer record --------------------------
CUSNUM = 1001;
CUSNAM = 'ACME Corporation';
CUSADR = '123 Main Street, Springfield';
CUSBAL = 5000.00;
CUSDAT = %Int(%Char(%Date():*ISO0));

Chain CUSNUM CUSRCD;
If Not %Found(CUSFILE);
  Write CUSRCD;
  Dsply 'Customer 1001 added successfully.';
Else;
  Dsply 'Customer 1001 already exists.';
EndIf;

// --- ADD a second customer ------------------------------
CUSNUM = 1002;
CUSNAM = 'Global Trading Ltd';
CUSADR = '456 Commerce Ave, Metropolis';
CUSBAL = 12500.75;
CUSDAT = %Int(%Char(%Date():*ISO0));

Chain CUSNUM CUSRCD;
If Not %Found(CUSFILE);
  Write CUSRCD;
  Dsply 'Customer 1002 added successfully.';
Else;
  Dsply 'Customer 1002 already exists.';
EndIf;

// --- READ a specific customer by key --------------------
CUSNUM = 1001;
Chain CUSNUM CUSRCD;
If %Found(CUSFILE);
  Dsply ('Found: ' + %TrimR(CUSNAM));
Else;
  Dsply 'Customer 1001 not found.';
EndIf;

// --- LIST all customers (sequential read) ---------------
SetLL *LoVal CUSRCD;
Read CUSRCD;
DoW Not %EOF(CUSFILE);
  Dsply (%TrimR(CUSNAM) + ' Bal:' + %Char(CUSBAL));
  Read CUSRCD;
EndDo;

*InLR = *On;
Return;

      **FREE
// ============================================================
// Module   : UTILS
// Purpose  : Service Program - Reusable Utility Procedures
// Author   : IBM i Project
// Date     : 2025
//
// Procedures exported:
//   FormatCurrency  - Format numeric value as currency string
//   GetCurrentDate  - Return current date as 8-digit YYYYMMDD
//   PadLeft         - Left-pad a string with a given character
//   IsNumeric       - Validate if a string contains only digits
// ============================================================

Ctl-Opt DftActGrp(*No) ActGrp(*Caller) NoMain Option(*SrcStmt);

// ============================================================
// Procedure : FormatCurrency
// Purpose   : Format a packed decimal as a currency string
//             e.g., 1234.56 -> '$1,234.56'
// ============================================================
Dcl-Proc FormatCurrency Export;
  Dcl-PI *N Char(20);
    pAmount Packed(11:2) Const;
  End-PI;

  Dcl-S wFormatted Char(20);

  wFormatted = '$' + %EditC(pAmount : '1');
  Return %TrimL(wFormatted);
End-Proc;

// ============================================================
// Procedure : GetCurrentDate
// Purpose   : Return today's date as an 8-digit numeric YYYYMMDD
// ============================================================
Dcl-Proc GetCurrentDate Export;
  Dcl-PI *N Packed(8:0);
  End-PI;

  Return %Int(%Char(%Date() : *ISO0));
End-Proc;

// ============================================================
// Procedure : PadLeft
// Purpose   : Left-pad a string to a target length with a char
//             e.g., PadLeft('42', 5, '0') -> '00042'
// ============================================================
Dcl-Proc PadLeft Export;
  Dcl-PI *N Char(50);
    pValue   Char(50)  Const;
    pLen     Int(3)    Const;
    pPadChar Char(1)   Const;
  End-PI;

  Dcl-S wResult Char(50);
  Dcl-S wTrimmed Char(50);

  wTrimmed = %TrimL(pValue);
  If %Len(%TrimR(wTrimmed)) >= pLen;
    Return %TrimR(wTrimmed);
  EndIf;

  wResult = %PadR(%PadR(pPadChar : pLen - %Len(%TrimR(wTrimmed)) : pPadChar)
            + %TrimR(wTrimmed) : 50);
  Return wResult;
End-Proc;

// ============================================================
// Procedure : IsNumeric
// Purpose   : Return *On if input string contains only digits
// ============================================================
Dcl-Proc IsNumeric Export;
  Dcl-PI *N Ind;
    pValue Char(50) Const;
  End-PI;

  Dcl-S wIdx    Int(3);
  Dcl-S wChar   Char(1);
  Dcl-S wTrimmed Char(50);

  wTrimmed = %TrimR(pValue);
  If wTrimmed = *Blanks;
    Return *Off;
  EndIf;

  For wIdx = 1 to %Len(%TrimR(wTrimmed));
    wChar = %SubSt(wTrimmed : wIdx : 1);
    If wChar < '0' Or wChar > '9';
      Return *Off;
    EndIf;
  EndFor;

  Return *On;
End-Proc;

