      **FREE
// ============================================================
// Program  : CUSMAINTP
// Purpose  : Interactive Customer Maintenance
//            - Uses CUSMAINT display file
//            - Calls UTILS service program procedures
//            - Performs Add / Change / Delete on CUSFILE
// Author   : IBM i Project
// Date     : 2025
//
// Function Keys:
//   F3  = Exit
//   F5  = Refresh / Re-read record
//   F12 = Cancel
// ============================================================

Ctl-Opt DftActGrp(*No) ActGrp(*Caller) BndDir('UTILBND') Option(*SrcStmt);

// ----- File Declarations --------------------------------
Dcl-F CUSMAINT WorkStn Indds(wIndDS);
Dcl-F CUSFILE  Usage(*Update:*Output:*Delete) Keyed;

// ----- Prototype for UTILS Service Program procedures ---
/Copy QRPGLESRC,UTILSPROT

// ----- Indicator Data Structure -------------------------
Dcl-DS wIndDS;
  wF3Exit    Ind Pos(3);
  wF5Refresh Ind Pos(5);
  wF12Cancel Ind Pos(12);
  wErrNotFnd Ind Pos(51);
  wErrDupKey Ind Pos(52);
End-DS;

// ----- Data Structures ----------------------------------
Dcl-DS dsCus ExtName('CUSFILE') End-DS;

// ----- Variables ----------------------------------------
Dcl-S wMode    Char(1)  Inz('A');   // A=Add  C=Change  D=Delete
Dcl-S wCurBal  Char(20);

// ----- Main Loop ----------------------------------------
Write HEADER;
DoU wF3Exit;

  // Clear error indicators
  wErrNotFnd = *Off;
  wErrDupKey = *Off;

  // Show the screen and wait for user input
  Exfmt CUSSCR;

  // F3 - Exit
  If wF3Exit;
    Leave;
  EndIf;

  // F12 - Cancel / clear screen
  If wF12Cancel;
    Clear dsCus;
    SCUSNUM = 0;
    SCUSNAM = *Blanks;
    SCUSADR = *Blanks;
    SCUSBAL = 0;
    SCUSDAT = 0;
    Iter;
  EndIf;

  // F5 - Refresh: re-read record from file
  If wF5Refresh;
    CUSNUM = SCUSNUM;
    Chain CUSNUM CUSRCD;
    If %Found(CUSFILE);
      SCUSNAM = CUSNAM;
      SCUSADR = CUSADR;
      SCUSBAL = CUSBAL;
      SCUSDAT = CUSDAT;
      wCurBal = FormatCurrency(CUSBAL);
      Dsply ('Balance: ' + %TrimR(wCurBal));
    Else;
      wErrNotFnd = *On;
    EndIf;
    Iter;
  EndIf;

  // Determine action: if record exists -> Change, else -> Add
  CUSNUM = SCUSNUM;
  Chain CUSNUM CUSRCD;

  If %Found(CUSFILE);
    // --- CHANGE existing record -------------------------
    CUSNAM = SCUSNAM;
    CUSADR = SCUSADR;
    CUSBAL = SCUSBAL;
    CUSDAT = GetCurrentDate();
    Update CUSRCD;
    Dsply 'Record updated.';
  Else;
    // --- ADD new record ---------------------------------
    CUSNUM = SCUSNUM;
    CUSNAM = SCUSNAM;
    CUSADR = SCUSADR;
    CUSBAL = SCUSBAL;
    CUSDAT = GetCurrentDate();
    Write CUSRCD;
    Dsply 'Record added.';
  EndIf;

EndDo;

*InLR = *On;
Return;

      **FREE
// ============================================================
// File     : UTILSPROT
// Purpose  : Prototype definitions for UTILS Service Program
//            /Copy this member into any program that calls UTILS
// Author   : IBM i Project
// Date     : 2025
// ============================================================

// --- FormatCurrency --------------------------------------
Dcl-PR FormatCurrency Char(20) ExtProc('FormatCurrency');
  pAmount Packed(11:2) Const;
End-PR;

// --- GetCurrentDate --------------------------------------
Dcl-PR GetCurrentDate Packed(8:0) ExtProc('GetCurrentDate');
End-PR;

// --- PadLeft ---------------------------------------------
Dcl-PR PadLeft Char(50) ExtProc('PadLeft');
  pValue   Char(50) Const;
  pLen     Int(3)   Const;
  pPadChar Char(1)  Const;
End-PR;

// --- IsNumeric -------------------------------------------
Dcl-PR IsNumeric Ind ExtProc('IsNumeric');
  pValue Char(50) Const;
End-PR;

/* ============================================================ */
/* Program  : MKBNDDIR                                         */
/* Purpose  : Build script - Create binding directory and      */
/*            register UTILS service program                   */
/* Author   : IBM i Project                                    */
/* Date     : 2025                                             */
/*                                                             */
/* Run this CL once after compiling UTILS to set up the        */
/* binding directory used by all programs in this project.     */
/* ============================================================ */
PGM PARM(&LIB)

    DCL VAR(&LIB) TYPE(*CHAR) LEN(10)

    /* --- Step 1: Compile the UTILS module ----------------- */
    CRTRPGMOD MODULE(&LIB/UTILS) +
              SRCFILE(&LIB/QRPGLESRC) +
              SRCMBR(UTILS) +
              DBGVIEW(*SOURCE)

    /* --- Step 2: Create the Service Program --------------- */
    CRTSRVPGM SRVPGM(&LIB/UTILS) +
              MODULE(&LIB/UTILS) +
              EXPORT(*ALL) +
              TEXT('Utility Service Program') +
              ACTGRP(*CALLER)

    /* --- Step 3: Create the Binding Directory ------------- */
    CRTBNDDIR BNDDIR(&LIB/UTILBND) +
              TEXT('Utility Binding Directory')

    /* --- Step 4: Add UTILS service program to bnd dir ----- */
    ADDBNDDIRE BNDDIR(&LIB/UTILBND) +
               OBJ((*LIBL/UTILS *SRVPGM))

    SNDPGMMSG MSG('UTILBND binding directory created successfully.') +
              TOPGMQ(*EXT) MSGTYPE(*INFO)

ENDPGM

