      **FREE
// ============================================================
// Program  : CUSSQL
// Purpose  : SQL-based Customer Query using Embedded SQL
// Author   : IBM i Project
// Date     : 2025
//
// Demonstrates:
//   - DECLARE CURSOR with WHERE and ORDER BY
//   - FETCH loop with null-safe host variables
//   - INSERT via SQL
//   - UPDATE via SQL
//   - DELETE via SQL
//   - SQLCODE / SQLSTATE error checking
// ============================================================

Ctl-Opt DftActGrp(*No) ActGrp(*Caller) Option(*SrcStmt);

// ----- Host Variables -----------------------------------
Dcl-S hCusNum   Packed(7:0);
Dcl-S hCusNam   Char(30);
Dcl-S hCusAdr   Char(40);
Dcl-S hCusBal   Packed(11:2);
Dcl-S hCusDat   Packed(8:0);
Dcl-S hMinBal   Packed(11:2)  Inz(1000.00);
Dcl-S wMsg      Char(80);

// ============================================================
// 1. INSERT a new customer via SQL
// ============================================================
hCusNum = 2001;
hCusNam = 'SQL Customer One';
hCusAdr = '789 Query Lane, Database City';
hCusBal = 9999.99;
hCusDat = 20250101;

Exec SQL
  INSERT INTO CUSFILE (CUSNUM, CUSNAM, CUSADR, CUSBAL, CUSDAT)
  VALUES (:hCusNum, :hCusNam, :hCusAdr, :hCusBal, :hCusDat);

If SQLCODE = 0;
  Dsply 'INSERT successful.';
ElseIf SQLCODE = -803;
  Dsply 'INSERT skipped: duplicate key.';
Else;
  wMsg = 'INSERT failed. SQLCODE=' + %Char(SQLCODE);
  Dsply wMsg;
EndIf;

// ============================================================
// 2. UPDATE balance for a specific customer via SQL
// ============================================================
hCusNum = 2001;
hCusBal = 15000.00;

Exec SQL
  UPDATE CUSFILE
     SET CUSBAL = :hCusBal,
         CUSDAT = INT(CHAR(CURRENT DATE, ISO))
   WHERE CUSNUM = :hCusNum;

If SQLCODE = 0;
  Dsply 'UPDATE successful.';
Else;
  wMsg = 'UPDATE failed. SQLCODE=' + %Char(SQLCODE);
  Dsply wMsg;
EndIf;

// ============================================================
// 3. CURSOR: List all customers with balance >= hMinBal
// ============================================================
Exec SQL
  DECLARE CUSCUR CURSOR FOR
    SELECT CUSNUM, CUSNAM, CUSADR, CUSBAL, CUSDAT
      FROM CUSFILE
     WHERE CUSBAL >= :hMinBal
     ORDER BY CUSBAL DESC;

Exec SQL OPEN CUSCUR;

Exec SQL
  FETCH NEXT FROM CUSCUR
  INTO :hCusNum, :hCusNam, :hCusAdr, :hCusBal, :hCusDat;

DoW SQLCODE = 0;
  wMsg = %TrimR(hCusNam) + ' $' + %Char(hCusBal);
  Dsply wMsg;

  Exec SQL
    FETCH NEXT FROM CUSCUR
    INTO :hCusNum, :hCusNam, :hCusAdr, :hCusBal, :hCusDat;
EndDo;

Exec SQL CLOSE CUSCUR;

// ============================================================
// 4. DELETE a customer via SQL
// ============================================================
hCusNum = 2001;

Exec SQL
  DELETE FROM CUSFILE WHERE CUSNUM = :hCusNum;

If SQLCODE = 0;
  Dsply 'DELETE successful.';
Else;
  wMsg = 'DELETE failed. SQLCODE=' + %Char(SQLCODE);
  Dsply wMsg;
EndIf;

*InLR = *On;
Return;

      **FREE
// ============================================================
// Module   : ERRLOG
// Purpose  : Error Logging via QMHSNDPM API
//            Sends a message to the program message queue,
//            the job log, or a named message queue.
// Author   : IBM i Project
// Date     : 2025
//
// Procedures exported:
//   LogInfo    - Send informational message to job log
//   LogError   - Send escape/diagnostic message to job log
//   SndMsgQ    - Send a message to a named message queue
// ============================================================

Ctl-Opt DftActGrp(*No) ActGrp(*Caller) NoMain Option(*SrcStmt);

// ----- QMHSNDPM API Prototype ---------------------------
// Send Program Message
Dcl-PR QMHSNDPM ExtPgm('QMHSNDPM');
  MsgId       Char(7)       Const;          // Message ID (*NONE for immediate)
  MsgFile     Char(20)      Const;          // Qualified message file
  MsgData     Char(512)     Const;          // Message data / substitution text
  MsgDataLen  Int(10)       Const;          // Length of message data
  MsgType     Char(10)      Const;          // *INFO *DIAG *ESCAPE *COMP
  CallStack   Char(10)      Const;          // Call stack entry (*PGMBDY *EXT)
  CallStkCnt  Int(10)       Const;          // Call stack counter
  MsgKey      Char(4);                      // Message key (output)
  ErrorDS     Char(256)     Options(*VarSize); // Error data structure
End-PR;

// ----- Error Code Data Structure ------------------------
Dcl-DS dsErrCode;
  ecBytesProvided  Int(10)  Inz(%Size(dsErrCode));
  ecBytesAvail     Int(10)  Inz(0);
  ecMsgId          Char(7);
  ecReserved       Char(1);
  ecMsgData        Char(240);
End-DS;

// ============================================================
// Procedure : LogInfo
// Purpose   : Send an *INFO immediate message to the job log
// ============================================================
Dcl-Proc LogInfo Export;
  Dcl-PI *N;
    pMsg Char(256) Const;
  End-PI;

  Dcl-S wKey     Char(4);
  Dcl-S wMsgLen  Int(10);
  Dcl-S wMsg     Char(256);

  wMsg    = %TrimR(pMsg);
  wMsgLen = %Len(%TrimR(wMsg));

  QMHSNDPM( '*NONE   '      // No message ID - immediate text
           : '                    ' // No message file needed
           : wMsg
           : wMsgLen
           : '*INFO     '
           : '*PGMBDY   '
           : 1
           : wKey
           : dsErrCode );
End-Proc;

// ============================================================
// Procedure : LogError
// Purpose   : Send a *DIAG immediate message to the job log
// ============================================================
Dcl-Proc LogError Export;
  Dcl-PI *N;
    pMsg Char(256) Const;
  End-PI;

  Dcl-S wKey     Char(4);
  Dcl-S wMsgLen  Int(10);
  Dcl-S wMsg     Char(256);

  wMsg    = %TrimR(pMsg);
  wMsgLen = %Len(%TrimR(wMsg));

  QMHSNDPM( '*NONE   '
           : '                    '
           : wMsg
           : wMsgLen
           : '*DIAG     '
           : '*PGMBDY   '
           : 1
           : wKey
           : dsErrCode );
End-Proc;

// ============================================================
// Procedure : SndMsgQ
// Purpose   : Send an *INFO message to a named message queue
//             pMsgQ format: 'MSGQNAME  LIBNAME   '  (20 chars)
// ============================================================
Dcl-Proc SndMsgQ Export;
  Dcl-PI *N;
    pMsgQ Char(20) Const;   // Qualified message queue name
    pMsg  Char(256) Const;
  End-PI;

  Dcl-S wKey     Char(4);
  Dcl-S wMsgLen  Int(10);
  Dcl-S wMsg     Char(256);

  wMsg    = %TrimR(pMsg);
  wMsgLen = %Len(%TrimR(wMsg));

  QMHSNDPM( '*NONE   '
           : '                    '
           : wMsg
           : wMsgLen
           : '*INFO     '
           : pMsgQ
           : 0
           : wKey
           : dsErrCode );
End-Proc;

