// ============================================================
// File     : ERRLOGPROT
// Purpose  : Prototype definitions for ERRLOG Service Program
//            /Copy this member into any program that calls ERRLOG
// Author   : IBM i Project
// Date     : 2025
// ============================================================

// --- LogInfo ---------------------------------------------
Dcl-PR LogInfo ExtProc('LogInfo');
  pMsg Char(256) Const;
End-PR;

// --- LogError --------------------------------------------
Dcl-PR LogError ExtProc('LogError');
  pMsg Char(256) Const;
End-PR;

// --- SndMsgQ ---------------------------------------------
