      **FREE
// ============================================================
// Program  : CUSLISTP
// Purpose  : Customer List Subfile Program
// Author   : IBM i Project
// Date     : 2025
//
// Subfile options:
//   2 = Change  (calls CUSMAINTP)
//   4 = Delete  (confirms and deletes)
//   5 = Display (read-only view)
//
// Function keys:
//   F3 = Exit
//   F5 = Refresh (reload subfile from file)
//   F6 = Add     (calls CUSMAINTP)
//   F12= Cancel
// ============================================================

Ctl-Opt DftActGrp(*No) ActGrp(*Caller) BndDir('UTILBND') Option(*SrcStmt);

// ----- File Declarations --------------------------------
Dcl-F CUSLIST   WorkStn Indds(wIndDS) SFile(SFLRCD : wRRN);
Dcl-F CUSFILE   Usage(*Input:*Delete) Keyed;
Dcl-F CUSBYNAM  Usage(*Input) Keyed;     // For position-to by name

// ----- Prototypes (ERRLOG service program) --------------
/Copy QRPGLESRC,ERRLOGPROT

// ----- Indicator Data Structure -------------------------
Dcl-DS wIndDS;
  wF3Exit    Ind Pos(3);
  wF5Refresh Ind Pos(5);
  wF6Add     Ind Pos(6);
  wF12Cancel Ind Pos(12);
  wSflDsp    Ind Pos(31);
  wSflClr    Ind Pos(32);
  wSflEnd    Ind Pos(33);
End-DS;

// ----- Variables ----------------------------------------
Dcl-S wRRN      Int(10)  Inz(0);
Dcl-S wPosNam   Char(30) Inz(*Blanks);
Dcl-S wMsg      Char(80);
