// ============================================================
// Program  : CUSRPTP
// Purpose  : Customer Balance Report - Print File Driver
// Author   : IBM i Project
// Date     : 2025
//
// Reads CUSFILE sequentially and prints:
//   - Page header with date/time and page number
//   - Column headings
//   - Detail line per customer
//   - Grand total (count + total balance)
//   - Page footer
// ============================================================

Ctl-Opt DftActGrp(*No) ActGrp(*Caller) BndDir('UTILBND') Option(*SrcStmt);

// ----- File Declarations --------------------------------
Dcl-F CUSRPT  Printer OflInd(*In99);
Dcl-F CUSFILE Usage(*Input);

// ----- Prototypes ---------------------------------------
/Copy QRPGLESRC,UTILSPROT
/Copy QRPGLESRC,ERRLOGPROT

// ----- Variables ----------------------------------------
Dcl-S wPageNum  Int(5)       Inz(0);
Dcl-S wRecCount Int(5)       Inz(0);
Dcl-S wTotBal   Packed(13:2) Inz(0);
Dcl-S wRunDate  Char(8);
Dcl-S wRunTime  Char(6);

// ----- Data Structure for customer record ---------------
