// Read all customers and print detail lines
Read CUSRCD;
DoW Not %EOF(CUSFILE);

  // Overflow check - new page header if needed
  If *In99;
    ExSr PrtHeader;
  EndIf;

  // Detail line
  DRCUSNUM = CUSNUM;
  DRCUSNAM = CUSNAM;
  DRCUSADR = CUSADR;
  DRCUSBAL = CUSBAL;
  DRCUSDAT = CUSDAT;
  Write DETAIL;

  // Accumulate totals
