TOTBAL = wTotBal;
Write TOTAL;

// Page footer
Write PAGEFOOT;

// Log completion
LogInfo('CUSRPTP: Report complete. Records=' + %Char(wRecCount)
      + ' TotalBal=' + FormatCurrency(wTotBal));

*InLR = *On;
Return;

