// SubRoutine : PrtHeader - Print page header and column heads
// ============================================================
BegSr PrtHeader;
  wPageNum += 1;
  RPTPAG    = wPageNum;
  RPTDAT    = wRunDate;
  RPTTIM    = wRunTime;
  Write RPTHEAD;
  Write COLHEAD;
