STRPGMEXP PGMLVL(*CURRENT) SIGNATURE('ERRLOG_V1')

  EXPORT SYMBOL('LogInfo')
  EXPORT SYMBOL('LogError')
  EXPORT SYMBOL('SndMsgQ')

ENDPGMEXP

