/* ============================================================ */
/* Program  : MKBNDDIR                                         */
/* Purpose  : Build script - Create binding directory and      */
/*            register UTILS + ERRLOG service programs         */
/* Author   : IBM i Project                                    */
/* Date     : 2025                                             */
/*                                                             */
/* Run this CL once after compiling sources to set up the      */
/* binding directory used by all programs in this project.     */
/* ============================================================ */
PGM PARM(&LIB)

    DCL VAR(&LIB) TYPE(*CHAR) LEN(10)

    /* === UTILS Service Program =========================== */

    /* --- Step 1: Compile the UTILS module ---------------- */
    CRTRPGMOD MODULE(&LIB/UTILS) +
              SRCFILE(&LIB/QRPGLESRC) +
              SRCMBR(UTILS) +
              DBGVIEW(*SOURCE)

    /* --- Step 2: Create the UTILS Service Program -------- */
    CRTSRVPGM SRVPGM(&LIB/UTILS) +
              MODULE(&LIB/UTILS) +
              EXPORT(*ALL) +
              TEXT('Utility Service Program') +
              ACTGRP(*CALLER)

    /* === ERRLOG Service Program ========================== */

    /* --- Step 3: Compile the ERRLOG module --------------- */
    CRTRPGMOD MODULE(&LIB/ERRLOG) +
              SRCFILE(&LIB/QRPGLESRC) +
              SRCMBR(ERRLOG) +
              DBGVIEW(*SOURCE)

    /* --- Step 4: Create the ERRLOG Service Program ------- */
    CRTSRVPGM SRVPGM(&LIB/ERRLOG) +
              MODULE(&LIB/ERRLOG) +
              EXPORT(*ALL) +
              TEXT('Error Logging Service Program') +
              ACTGRP(*CALLER)

    /* === Binding Directory =============================== */

    /* --- Step 5: Create the Binding Directory ------------ */
    CRTBNDDIR BNDDIR(&LIB/UTILBND) +
              TEXT('Project Binding Directory')

    /* --- Step 6: Add both service programs --------------- */
    ADDBNDDIRE BNDDIR(&LIB/UTILBND) +
               OBJ((*LIBL/UTILS *SRVPGM) +
                   (*LIBL/ERRLOG *SRVPGM))

    SNDPGMMSG MSG('UTILBND binding directory created successfully.') +
              TOPGMQ(*EXT) MSGTYPE(*INFO)

ENDPGM

